<?php require '_header.php';$page_title='Payment reviews';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$status=$_POST['status']??'';if(in_array($status,['submitted','verified','rejected'],true)){$q=$pdo->prepare('UPDATE payments SET status=?,note=? WHERE id=?');$q->execute([$status,trim($_POST['note']??'')?:null,(int)$_POST['id']]);flash('Payment review status updated.');redirect('payments.php');}}$rows=$pdo->query('SELECT p.*,u.name user_name,u.email,d.name destination FROM payments p JOIN users u ON u.id=p.user_id JOIN bookings b ON b.id=p.booking_id JOIN destinations d ON d.id=b.destination_id ORDER BY p.created_at DESC')->fetchAll();?><div class="admin-top"><div><span class="eyebrow">PAYMENT RECONCILIATION</span><h1>Payment submissions</h1><p class="muted">Verify UTR/reference against your bank or payment provider before marking verified.</p></div></div><?php if(!$rows):?><div class="empty">No payment submissions yet.</div><?php else:?><div class="table-wrap"><table><tr><th>Customer / trip</th><th>Amount / method</th><th>Reference</th><th>Status review</th></tr><?php foreach($rows as $r):?><tr><td><b><?=e($r['user_name'])?></b><br><?=e($r['email'])?><br><?=e($r['destination'])?></td><td>₹<?=number_format((float)$r['amount'],2)?><br><?=e($r['method'])?></td><td><?=e($r['transaction_ref'])?><br><small><?=e($r['created_at'])?></small></td><td><span class="status <?=e($r['status'])?>"><?=e($r['status'])?></span><form method="post" class="inline-form" style="margin-top:8px"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option value="submitted">Submitted</option><option value="verified">Verified</option><option value="rejected">Rejected</option></select><input name="note" placeholder="Admin note"><button class="small-btn">Save</button></form></td></tr><?php endforeach;?></table></div><?php endif;?><?php require '_footer.php';?>
